'use strict';
const fs=require('fs'),{createDispatcher}=require('../../../scripts/improve-service-dispatch.cjs'),proc=require('../../../scripts/improve-process-identity.cjs');
const [hostFile,repo_id,run_id,cut,observation]=process.argv.slice(2);
createDispatcher(hostFile,{fault:(point,data)=>{if(point===cut){let childPid=data.pid;try{if(!childPid){const host=JSON.parse(fs.readFileSync(hostFile));childPid=JSON.parse(fs.readFileSync(require('path').join(host.store,'controller.json'))).runs[run_id].service.dispatch.process?.pid;}}catch{}let childArgv=null;try{if(childPid)childArgv=fs.readFileSync('/proc/'+childPid+'/cmdline','utf8').split('\0').filter(Boolean);}catch{}fs.writeFileSync(observation,JSON.stringify({point,data,coordinator:proc.identity(),child:childPid?proc.identity(childPid):null,childArgv}),{mode:0o600});process.kill(process.pid,'SIGKILL');}}}).dispatch({repo_id,run_id}).then(()=>{process.exitCode=0;}).catch(e=>{fs.writeFileSync(observation,JSON.stringify({failed:e.code||'dispatch_failed'}),{mode:0o600});process.exitCode=2;});
